package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues2D_removeColumn_TriageGen2Test {

    private DefaultKeyedValues2D dataset;

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues2D();
    }



    @Test
    public void testRemoveColumnSuccess() {
        // Setup data
        Comparable row1 = "Row1";
        Comparable row2 = "Row2";
        Comparable col1 = "Col1";
        Comparable col2 = "Col2";

        dataset.addValue(10.0, row1, col1);
        dataset.addValue(20.0, row1, col2);
        dataset.addValue(30.0, row2, col1);
        dataset.addValue(40.0, row2, col2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals(10.0, dataset.getValue(row1, col1).doubleValue(), 0.001);

        // Execute removal
        dataset.removeColumn(col1);

        // Verify column is removed from columnKeys
        List<Comparable> columnKeys = dataset.getColumnKeys();
        assertEquals(1, columnKeys.size());
        assertEquals(col2, columnKeys.get(0));

        // Verify values associated with col1 are gone
        assertNull(dataset.getValue(row1, col1));
        assertNull(dataset.getValue(row2, col1));

        // Verify other data remains intact
        assertEquals(20.0, dataset.getValue(row1, col2).doubleValue(), 0.001);
        assertEquals(40.0, dataset.getValue(row2, col2).doubleValue(), 0.001);
        assertEquals(2, dataset.getRowCount());
    }






}

