package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues2D_removeColumn_TriageGen2Test {

    private DefaultKeyedValues2D dataset;

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues2D();
    }









    @Test
    public void testRemoveColumnWithPartialRowData() {
        // Setup data where one row has the column and another does not
        Comparable row1 = "Row1";
        Comparable row2 = "Row2";
        Comparable col1 = "Col1";
        Comparable col2 = "Col2";

        dataset.addValue(10.0, row1, col1);
        // Row 2 does not have col1
        dataset.addValue(20.0, row2, col2);

        dataset.removeColumn(col1);

        // Verify col1 is gone
        assertNull(dataset.getValue(row1, col1));
        // Verify col2 and row2 data remains
        assertEquals(20.0, dataset.getValue(row2, col2).doubleValue(), 0.001);
        assertEquals(1, dataset.getColumnCount());
    }
}
